// Payload layouts, cross-checked against the meshkit Python implementation.
//
// The VEC_* vectors below were produced by the Python codec. Decoding them here
// and getting the expected fields back is what proves the two implementations
// agree on the wire, rather than merely agreeing with themselves.

#include "TestUtil.h"
#include <Arduino.h>
#include <unity.h>

#include "modem/ModemCodec.h"
#include <cstdio>
#include <cstring>

// Generated by the Python codec - see meshkit/python.
