// ---------------------------------------------------------------------------
// Group C1 - decode the Python vectors

static void test_C1a_position()
{
    ModemPosition p;
    TEST_ASSERT_TRUE(modemDecodePosition(VEC_POSITION, sizeof(VEC_POSITION), &p));
    TEST_ASSERT_EQUAL_INT32(375665000, p.latitude_i);
    TEST_ASSERT_EQUAL_INT32(1269780000, p.longitude_i);
    TEST_ASSERT_EQUAL_INT32(38, p.altitude_m);
    TEST_ASSERT_EQUAL_UINT32(1700000000u, p.timestamp_unix);
    TEST_ASSERT_EQUAL_UINT8(3, p.fix_type);
    TEST_ASSERT_EQUAL_UINT8(9, p.sats_in_view);
}

static void test_C1b_position_negative_coordinates()
{
    ModemPosition p;
    TEST_ASSERT_TRUE(modemDecodePosition(VEC_POSITION_SOUTH, sizeof(VEC_POSITION_SOUTH), &p));
    TEST_ASSERT_EQUAL_INT32(-338688000, p.latitude_i);
    TEST_ASSERT_EQUAL_INT32(-1512093000, p.longitude_i);
}

static void test_C1c_region_profile()
{
    ModemRegionProfile r;
    TEST_ASSERT_TRUE(modemDecodeRegionProfile(VEC_REGION, sizeof(VEC_REGION), &r));
    TEST_ASSERT_EQUAL_UINT8(12, r.region);
    TEST_ASSERT_FALSE(r.use_preset);
    TEST_ASSERT_EQUAL_UINT32(250000u, r.bandwidth_hz);
    TEST_ASSERT_EQUAL_UINT8(11, r.spread_factor);
    TEST_ASSERT_EQUAL_UINT8(5, r.coding_rate);
    TEST_ASSERT_EQUAL_UINT8(20, r.channel_num);
    TEST_ASSERT_TRUE(r.override_duty_cycle);
    TEST_ASSERT_EQUAL_UINT32(923000000u, r.override_freq_hz);
}

static void test_C1d_tx_params_negative_power()
{
    ModemTxParams t;
    TEST_ASSERT_TRUE(modemDecodeTxParams(VEC_TXPARAMS, sizeof(VEC_TXPARAMS), &t));
    TEST_ASSERT_EQUAL_INT8(-5, t.tx_power_dbm);
    TEST_ASSERT_EQUAL_UINT8(3, t.hop_limit);
    TEST_ASSERT_FALSE(t.tx_enabled);
}

static void test_C1e_identity()
{
    ModemIdentity id;
    TEST_ASSERT_TRUE(modemDecodeIdentity(VEC_IDENTITY, sizeof(VEC_IDENTITY), &id));
    TEST_ASSERT_EQUAL_UINT8(6, id.role);
    TEST_ASSERT_TRUE(id.is_unmessagable);
    TEST_ASSERT_EQUAL_UINT8(12, id.long_name_len);
    TEST_ASSERT_EQUAL_UINT8(3, id.short_name_len);
    TEST_ASSERT_EQUAL_MEMORY("Pump House 3", id.long_name, 12);
    TEST_ASSERT_EQUAL_MEMORY("PH3", id.short_name, 3);
}

static void test_C1f_channel()
{
    ModemChannel c;
    TEST_ASSERT_TRUE(modemDecodeChannel(VEC_CHANNEL, sizeof(VEC_CHANNEL), &c));
    TEST_ASSERT_EQUAL_UINT8(1, c.index);
    TEST_ASSERT_EQUAL_UINT8(2, c.role);
    TEST_ASSERT_EQUAL_UINT8(16, c.psk_len);
    TEST_ASSERT_EQUAL_UINT8(6, c.name_len);
    TEST_ASSERT_EQUAL_MEMORY("site-a", c.name, 6);
    for (uint8_t i = 0; i < 16; i++)
        TEST_ASSERT_EQUAL_UINT8(i, c.psk[i]);
}

static void test_C1g_rx_policy()
{
    ModemRxPolicy p;
    TEST_ASSERT_TRUE(modemDecodeRxPolicy(VEC_RXPOLICY, sizeof(VEC_RXPOLICY), &p));
    TEST_ASSERT_EQUAL_UINT8(MODEM_TEXT_RX_ALLOWLIST, p.text_rx_mode);
    TEST_ASSERT_EQUAL_UINT8(MODEM_PORTNUM_ALLOWLIST, p.portnum_mode);
    TEST_ASSERT_EQUAL_UINT16(233, p.max_payload_len);
    TEST_ASSERT_EQUAL_UINT16(20, p.uart_budget_pps);
    TEST_ASSERT_EQUAL_UINT16(512, p.per_sender_pps_q8);
    TEST_ASSERT_EQUAL_UINT8(3, p.portnum_count);
    TEST_ASSERT_EQUAL_UINT8(1, p.portnums[0]);
    TEST_ASSERT_EQUAL_UINT8(67, p.portnums[1]);
    TEST_ASSERT_EQUAL_UINT8(79, p.portnums[2]);

    uint32_t sender = 0;
    TEST_ASSERT_TRUE(modemRxPolicySender(&p, 0, &sender));
    TEST_ASSERT_EQUAL_HEX32(0xDEADBEEFu, sender);
    TEST_ASSERT_TRUE(modemRxPolicySender(&p, 1, &sender));
    TEST_ASSERT_EQUAL_HEX32(0x00C0FFEEu, sender);
    TEST_ASSERT_FALSE(modemRxPolicySender(&p, 2, &sender));
}

static void test_C1h_telemetry()
{
    ModemTelemetry t;
    TEST_ASSERT_TRUE(modemDecodeTelemetry(VEC_TELEMETRY, sizeof(VEC_TELEMETRY), &t));
    TEST_ASSERT_EQUAL_UINT8(2, t.variant);
    TEST_ASSERT_EQUAL_UINT8(2, t.metric_count);

    ModemMetric m;
    TEST_ASSERT_TRUE(modemTelemetryMetric(&t, 0, &m));
    TEST_ASSERT_EQUAL_UINT8(1, m.metric_id);
    TEST_ASSERT_EQUAL_INT8(-2, m.scale10);
    TEST_ASSERT_EQUAL_INT32(2350, m.value);

    TEST_ASSERT_TRUE(modemTelemetryMetric(&t, 1, &m));
    TEST_ASSERT_EQUAL_INT32(-40, m.value);
    TEST_ASSERT_FALSE(modemTelemetryMetric(&t, 2, &m));
    TEST_ASSERT_EQUAL_UINT8(0, t.text_len);
}

static void test_C1i_send_binary()
{
    ModemSendBinary s;
    TEST_ASSERT_TRUE(modemDecodeSendBinary(VEC_SENDBINARY, sizeof(VEC_SENDBINARY), &s));
    TEST_ASSERT_EQUAL_HEX32(0x1234u, s.dest_node);
    TEST_ASSERT_EQUAL_UINT16(300, s.portnum); // beyond a byte, in the private range
    TEST_ASSERT_EQUAL_UINT8(0x05, s.flags);   // want_ack | pki
    TEST_ASSERT_EQUAL_UINT8(3, s.hop_limit);
    TEST_ASSERT_EQUAL_UINT16(3, s.payload_len);
    TEST_ASSERT_EQUAL_MEMORY("\x01\x02\x03", s.payload, 3);
}

static void test_C1j_send_text_utf8()
{
    ModemSendText s;
    TEST_ASSERT_TRUE(modemDecodeSendText(VEC_SENDTEXT, sizeof(VEC_SENDTEXT), &s));
    TEST_ASSERT_EQUAL_HEX32(0x99u, s.dest_node);
    TEST_ASSERT_EQUAL_UINT8(1, s.channel_index);
    TEST_ASSERT_EQUAL_UINT16(13, s.text_len); // 4 Hangul syllables plus a space
}

static void test_C1k_security()
{
    ModemSecurity s;
    TEST_ASSERT_TRUE(modemDecodeSecurity(VEC_SECURITY, sizeof(VEC_SECURITY), &s));
    TEST_ASSERT_EQUAL_UINT8(32, s.key_len);
    TEST_ASSERT_FALSE(s.generate);
    for (uint8_t i = 0; i < 32; i++)
        TEST_ASSERT_EQUAL_UINT8(i, s.private_key[i]);
}

static void test_C1l_bootloader_magic()
{
    TEST_ASSERT_TRUE(modemDecodeEnterBootloader(VEC_BOOTLOADER, sizeof(VEC_BOOTLOADER)));

    const uint8_t wrong[] = {0x00, 0x00, 0x00, 0x00};
    TEST_ASSERT_FALSE(modemDecodeEnterBootloader(wrong, sizeof(wrong)));
}

// ---------------------------------------------------------------------------
// Group C2 - encoders produce the sizes the specification fixes

static void test_C2a_encoded_sizes()
{
    uint8_t buf[64];
    const uint8_t fw[3] = {2, 7, 27};

    TEST_ASSERT_EQUAL_UINT16(17, modemEncodeHelloReply(buf, sizeof(buf), MODEM_OK, 1, 7, 0xABCD, 0x1234, fw, 0));

    ModemConfigDigest digest = {};
    TEST_ASSERT_EQUAL_UINT16(16, modemEncodeConfigDigest(buf, sizeof(buf), MODEM_OK, &digest));

    ModemMeshStatus mesh = {};
    TEST_ASSERT_EQUAL_UINT16(32, modemEncodeMeshStatus(buf, sizeof(buf), MODEM_OK, &mesh));

    TEST_ASSERT_EQUAL_UINT16(8, modemEncodeSendReply(buf, sizeof(buf), MODEM_OK, 0xCAFE));

    ModemHealth health = {};
    TEST_ASSERT_EQUAL_UINT16(20, modemEncodeHealth(buf, sizeof(buf), &health));

    ModemTxStatus tx = {};
    TEST_ASSERT_EQUAL_UINT16(8, modemEncodeTxStatus(buf, sizeof(buf), &tx));

    ModemMeshState state = {};
    TEST_ASSERT_EQUAL_UINT16(8, modemEncodeMeshState(buf, sizeof(buf), &state));

    ModemRebooted rebooted = {};
    TEST_ASSERT_EQUAL_UINT16(8, modemEncodeRebooted(buf, sizeof(buf), &rebooted));

    ModemNodeEntry entry = {};
    TEST_ASSERT_EQUAL_UINT16(16, modemEncodeNodeEntry(buf, sizeof(buf), &entry));
    TEST_ASSERT_EQUAL_UINT8(0, buf[12]); // no signal strength field here - see the specification
}

static void test_C2b_send_reply_zeroes_tx_id_on_error()
{
    uint8_t buf[8];
    modemEncodeSendReply(buf, sizeof(buf), MODEM_ERR_TX_QUEUE_FULL, 0xCAFE);

    TEST_ASSERT_EQUAL_UINT8(MODEM_ERR_TX_QUEUE_FULL, buf[0]);
    for (int i = 4; i < 8; i++)
        TEST_ASSERT_EQUAL_UINT8(0, buf[i]);
}

static void test_C2c_health_field_placement()
{
    uint8_t buf[20];
    ModemHealth health = {};
    health.session_epoch = 9;
    health.uptime_s = 3600;
    health.node_count = 42;
    health.channel_util_pct = 30;
    health.air_util_tx_pct = 11;
    health.state = MODEM_STATE_UNDER_ATTACK;

    TEST_ASSERT_EQUAL_UINT16(20, modemEncodeHealth(buf, sizeof(buf), &health));
    TEST_ASSERT_EQUAL_UINT8(9, buf[0]);
    TEST_ASSERT_EQUAL_UINT8(42, buf[8]);
    TEST_ASSERT_EQUAL_UINT8(30, buf[14]);
    TEST_ASSERT_EQUAL_UINT8(11, buf[15]);
    TEST_ASSERT_EQUAL_UINT8(MODEM_STATE_UNDER_ATTACK, buf[16]);
    TEST_ASSERT_EQUAL_UINT8(0, buf[17]);
}

static void test_C2d_rx_headers_and_negative_rssi()
{
    uint8_t buf[64];

    ModemRxDataHeader data = {};
    data.from_node = 0x55;
    data.portnum = 67;
    data.rssi_dbm = -102;
    data.snr_q2 = -6;
    TEST_ASSERT_EQUAL_UINT16(18 + 3, modemEncodeRxData(buf, sizeof(buf), &data, (const uint8_t *)"abc", 3));
    TEST_ASSERT_EQUAL_UINT8(0x9A, buf[8]); // -102 as little-endian i16
    TEST_ASSERT_EQUAL_UINT8(0xFF, buf[9]);
    TEST_ASSERT_EQUAL_UINT8(0xFA, buf[10]); // -6 as i8
    TEST_ASSERT_EQUAL_MEMORY("abc", &buf[18], 3);

    ModemRxTextHeader text = {};
    text.from_node = 0x77;
    TEST_ASSERT_EQUAL_UINT16(17 + 2, modemEncodeRxText(buf, sizeof(buf), &text, (const uint8_t *)"ok", 2));
    TEST_ASSERT_EQUAL_MEMORY("ok", &buf[17], 2);
}

static void test_C2e_encoders_refuse_a_short_buffer()
{
    uint8_t buf[4];
    ModemHealth health = {};
    TEST_ASSERT_EQUAL_UINT16(0, modemEncodeHealth(buf, sizeof(buf), &health));

    ModemRxDataHeader data = {};
    TEST_ASSERT_EQUAL_UINT16(0, modemEncodeRxData(buf, sizeof(buf), &data, (const uint8_t *)"abc", 3));
}

static void test_C2f_rx_data_refuses_to_exceed_max_payload()
{
    static uint8_t buf[MODEM_MAX_PAYLOAD * 2];
    static uint8_t body[MODEM_MAX_PAYLOAD];
    ModemRxDataHeader data = {};

    TEST_ASSERT_EQUAL_UINT16(0, modemEncodeRxData(buf, sizeof(buf), &data, body, MODEM_MAX_PAYLOAD));
}

// ---------------------------------------------------------------------------
// Group C3 - malformed input

static void test_C3a_fixed_layouts_reject_wrong_length()
{
    const uint8_t one[1] = {0};
    ModemPosition p;
    ModemRegionProfile r;
    ModemTxParams t;
    ModemHello h;

    TEST_ASSERT_FALSE(modemDecodePosition(one, 1, &p));
    TEST_ASSERT_FALSE(modemDecodeRegionProfile(one, 1, &r));
    TEST_ASSERT_FALSE(modemDecodeTxParams(one, 1, &t));
    TEST_ASSERT_FALSE(modemDecodeHello(one, 1, &h));

    // A longer-than-specified payload is refused too: silent truncation hides bugs.
    uint8_t padded[MODEM_POSITION_SIZE + 1] = {};
    TEST_ASSERT_FALSE(modemDecodePosition(padded, sizeof(padded), &p));
}

static void test_C3b_declared_length_beyond_the_buffer_is_rejected()
{
    uint8_t frame[12] = {};
    frame[10] = 0xFF; // payload_len = 255 with nothing after it
    frame[11] = 0x00;

    ModemSendBinary s;
    TEST_ASSERT_FALSE(modemDecodeSendBinary(frame, sizeof(frame), &s));

    uint8_t text[8] = {};
    text[6] = 0xFF;
    ModemSendText t;
    TEST_ASSERT_FALSE(modemDecodeSendText(text, sizeof(text), &t));
}

static void test_C3c_channel_rejects_an_invalid_psk_length()
{
    uint8_t buf[32] = {};
    buf[2] = 8; // not one of 0, 1, 16, 32
    ModemChannel c;
    TEST_ASSERT_FALSE(modemDecodeChannel(buf, sizeof(buf), &c));
}

static void test_C3d_security_rejects_an_invalid_key_length()
{
    uint8_t buf[32] = {};
    buf[0] = 16;
    ModemSecurity s;
    TEST_ASSERT_FALSE(modemDecodeSecurity(buf, sizeof(buf), &s));
}

static void test_C3e_decoders_never_read_past_the_buffer()
{
    uint32_t state = 0xC0DEC0DEu;
    uint8_t scratch[64];

    for (unsigned iter = 0; iter < 20000; iter++) {
        state = state * 1103515245u + 12345u;
        const uint16_t len = (uint16_t)((state >> 16) % (sizeof(scratch) + 1));
        for (uint16_t i = 0; i < len; i++) {
            state = state * 1103515245u + 12345u;
            scratch[i] = (uint8_t)(state >> 16);
        }

        ModemIdentity id;
        ModemChannel ch;
        ModemSecurity se;
        ModemRxPolicy rp;
        ModemTelemetry te;
        ModemSendBinary sb;
        ModemSendText st;

        // Any of these may fail; none may read out of bounds. The sanitizers in
        // the coverage environment turn a violation into a failure.
        if (modemDecodeIdentity(scratch, len, &id))
            TEST_ASSERT_TRUE(4u + id.long_name_len + id.short_name_len <= len);
        if (modemDecodeChannel(scratch, len, &ch))
            TEST_ASSERT_TRUE(4u + ch.psk_len + ch.name_len <= len);
        if (modemDecodeSecurity(scratch, len, &se))
            TEST_ASSERT_TRUE(4u + se.key_len <= len);
        if (modemDecodeRxPolicy(scratch, len, &rp))
            TEST_ASSERT_TRUE(12u + rp.portnum_count + (uint32_t)rp.sender_count * 4u <= len);
        if (modemDecodeTelemetry(scratch, len, &te))
            TEST_ASSERT_TRUE(2u + (uint32_t)te.metric_count * 6u <= len);
        if (modemDecodeSendBinary(scratch, len, &sb))
            TEST_ASSERT_TRUE(10u + sb.payload_len <= len);
        if (modemDecodeSendText(scratch, len, &st))
            TEST_ASSERT_TRUE(8u + st.text_len <= len);
    }
}

