static void test_C4a_identity_reply_matches_the_host_vector()
{
    ModemIdentityInfo info = {};
    info.node_num = 0x500F2043u;
    info.role = 2;
    info.is_unmessagable = true;
    info.hw_model = 72;

    uint8_t buf[64] = {};
    const uint16_t len = modemEncodeIdentityReply(buf, sizeof(buf), MODEM_OK, &info, "RAK3172 Modem", "RK72");
    TEST_ASSERT_EQUAL_UINT16(sizeof(VEC_IDENTITY_REPLY), len);
    TEST_ASSERT_EQUAL_UINT8_ARRAY(VEC_IDENTITY_REPLY, buf, len);
}

static void test_C4b_node_info_matches_the_host_vector()
{
    ModemNodeInfo info = {};
    info.node_num = 0x2EDCA04Cu;
    info.last_heard = 1785652726u;
    info.latitude_i = 363596500;
    info.longitude_i = 1273976300;
    info.altitude_m = 50;
    info.position_time = 1785652700u;
    info.voltage_mv = 3987;
    info.snr_q2 = 26;
    info.hops_away = 2;
    info.role = 1;
    info.flags = 0x1B;
    info.battery_level = 94;

    uint8_t buf[96] = {};
    const uint16_t len = modemEncodeNodeInfo(buf, sizeof(buf), MODEM_OK, &info, "#IoTMadeEasy", "a04c");
    TEST_ASSERT_EQUAL_UINT16(sizeof(VEC_NODE_INFO), len);
    TEST_ASSERT_EQUAL_UINT8_ARRAY(VEC_NODE_INFO, buf, len);
}

static void test_C4c_name_encoders_refuse_a_buffer_that_cannot_hold_the_names()
{
    ModemIdentityInfo info = {};
    uint8_t buf[MODEM_IDENTITY_REPLY_HEAD_SIZE + 3] = {};

    TEST_ASSERT_EQUAL_UINT16(0, modemEncodeIdentityReply(buf, sizeof(buf), MODEM_OK, &info, "abcd", ""));
    TEST_ASSERT_EQUAL_UINT16(MODEM_IDENTITY_REPLY_HEAD_SIZE + 3,
                             modemEncodeIdentityReply(buf, sizeof(buf), MODEM_OK, &info, "abc", ""));
    TEST_ASSERT_EQUAL_UINT16(0, modemEncodeIdentityReply(buf, MODEM_IDENTITY_REPLY_HEAD_SIZE - 1, MODEM_OK, &info,
                                                         "", ""));
}

static void test_C4d_node_info_request_takes_exactly_four_bytes()
{
    const uint8_t good[4] = {0x4C, 0xA0, 0xDC, 0x2E};
    uint32_t num = 0;

    TEST_ASSERT_TRUE(modemDecodeNodeInfoRequest(good, sizeof(good), &num));
    TEST_ASSERT_EQUAL_UINT32(0x2EDCA04Cu, num);
    TEST_ASSERT_FALSE(modemDecodeNodeInfoRequest(good, 3, &num));
    TEST_ASSERT_FALSE(modemDecodeNodeInfoRequest(good, 5, &num));
}


static void test_C5a_telemetry_carries_a_trailing_string()
{
    const uint8_t vec[] = {0x06, 0x01, 0x01, 0x00, 0x10, 0x0E, 0x00, 0x00, 0x04, 'p', 'u', 'm', 'p'};

    ModemTelemetry t;
    TEST_ASSERT_TRUE(modemDecodeTelemetry(vec, sizeof(vec), &t));
    TEST_ASSERT_EQUAL_UINT8(6, t.variant);
    TEST_ASSERT_EQUAL_UINT8(1, t.metric_count);
    TEST_ASSERT_EQUAL_UINT8(4, t.text_len);
    TEST_ASSERT_EQUAL_MEMORY("pump", t.utf8, 4);
}

static void test_C5b_telemetry_rejects_a_string_past_the_buffer()
{
    uint8_t vec[9] = {0x06, 0x01, 0x01, 0x00, 0x10, 0x0E, 0x00, 0x00, 0x7F};

    ModemTelemetry t;
    TEST_ASSERT_FALSE(modemDecodeTelemetry(vec, sizeof(vec), &t));

    vec[8] = 0x00;
    TEST_ASSERT_TRUE(modemDecodeTelemetry(vec, sizeof(vec), &t));
}

static void test_C5c_utf8_accepts_well_formed_sequences()
{
    const uint8_t ascii[] = {'o', 'k'};
    const uint8_t hangul[] = {0xEC, 0x84, 0xA4, 0xEB, 0xB9, 0x84};
    const uint8_t emoji[] = {0xF0, 0x9F, 0x94, 0x8B};

    TEST_ASSERT_TRUE(modemIsValidUtf8(ascii, sizeof(ascii)));
    TEST_ASSERT_TRUE(modemIsValidUtf8(hangul, sizeof(hangul)));
    TEST_ASSERT_TRUE(modemIsValidUtf8(emoji, sizeof(emoji)));
    TEST_ASSERT_TRUE(modemIsValidUtf8(ascii, 0));
}

static void test_C5d_utf8_rejects_the_classic_malformations()
{
    const uint8_t truncated[] = {0xEC, 0x84};
    const uint8_t overlong[] = {0xC0, 0xAF};
    const uint8_t surrogate[] = {0xED, 0xA0, 0x80};
    const uint8_t too_high[] = {0xF5, 0x80, 0x80, 0x80};
    const uint8_t lone_continuation[] = {0x80};
    const uint8_t bad_continuation[] = {0xEC, 0x84, 0x41};

    TEST_ASSERT_FALSE(modemIsValidUtf8(truncated, sizeof(truncated)));
    TEST_ASSERT_FALSE(modemIsValidUtf8(overlong, sizeof(overlong)));
    TEST_ASSERT_FALSE(modemIsValidUtf8(surrogate, sizeof(surrogate)));
    TEST_ASSERT_FALSE(modemIsValidUtf8(too_high, sizeof(too_high)));
    TEST_ASSERT_FALSE(modemIsValidUtf8(lone_continuation, sizeof(lone_continuation)));
    TEST_ASSERT_FALSE(modemIsValidUtf8(bad_continuation, sizeof(bad_continuation)));
}


static void test_C6a_type_space_puts_every_response_in_its_own_quarter()
{
    for (unsigned t = 0x01; t <= 0x3F; t++) {
        TEST_ASSERT_TRUE(modemTypeIsCommand((uint8_t)t));
        TEST_ASSERT_TRUE(modemTypeIsCommandResponse(modemResponseFor((uint8_t)t)));
        TEST_ASSERT_EQUAL_UINT8(t, modemRequestFor(modemResponseFor((uint8_t)t)));
    }

    for (unsigned t = 0x40; t <= 0x7F; t++) {
        TEST_ASSERT_TRUE(modemTypeIsEvent((uint8_t)t));
        TEST_ASSERT_TRUE(modemTypeIsHostResponse(modemResponseFor((uint8_t)t)));
        TEST_ASSERT_EQUAL_UINT8(t, modemRequestFor(modemResponseFor((uint8_t)t)));
    }
}

static void test_C6b_the_four_kinds_never_overlap()
{
    for (unsigned t = 0; t <= 0xFF; t++) {
        const uint8_t type = (uint8_t)t;
        const unsigned kinds = (modemTypeIsCommand(type) ? 1u : 0u) + (modemTypeIsEvent(type) ? 1u : 0u) +
                               (modemTypeIsCommandResponse(type) ? 1u : 0u) + (modemTypeIsHostResponse(type) ? 1u : 0u);
        TEST_ASSERT_EQUAL_UINT32(type == 0x00 ? 0u : 1u, kinds);
    }
}

static void test_C6c_every_defined_command_stays_inside_its_range()
{
    const uint8_t commands[] = {MODEM_CMD_HELLO,         MODEM_CMD_GET_MODEM_STATUS, MODEM_CMD_SET_IDENTITY,
                                MODEM_CMD_SET_RX_POLICY, MODEM_CMD_GET_IDENTITY,     MODEM_CMD_GET_CONFIG_DIGEST,
                                MODEM_CMD_SET_POSITION,  MODEM_CMD_ANNOUNCE,         MODEM_CMD_GET_NODE_INFO,
                                MODEM_CMD_ENTER_BOOTLOADER};

    for (size_t i = 0; i < sizeof(commands) / sizeof(commands[0]); i++) {
        TEST_ASSERT_TRUE(modemTypeIsCommand(commands[i]));
        TEST_ASSERT_TRUE(modemTypeIsCommandResponse(modemResponseFor(commands[i])));
    }

    const uint8_t modemSide[] = {MODEM_EVT_REBOOTED, MODEM_EVT_HEALTH,    MODEM_EVT_RX_DATA,
                                 MODEM_EVT_RX_TEXT,  MODEM_EVT_TX_STATUS, MODEM_EVT_MESH_STATE,
                                 MODEM_QRY_TELEMETRY};

    for (size_t i = 0; i < sizeof(modemSide) / sizeof(modemSide[0]); i++)
        TEST_ASSERT_TRUE(modemTypeIsEvent(modemSide[i]));
}

static void test_C6d_query_telemetry_is_eight_bytes()
{
    uint8_t buf[MODEM_QUERY_TELEMETRY_SIZE] = {};
    TEST_ASSERT_EQUAL_UINT16(8, modemEncodeQueryTelemetry(buf, sizeof(buf), 0x2EDCA04Cu, 2));
    TEST_ASSERT_EQUAL_HEX8(0x4C, buf[0]);
    TEST_ASSERT_EQUAL_HEX8(0x2E, buf[3]);
    TEST_ASSERT_EQUAL_UINT8(2, buf[4]);
    TEST_ASSERT_EQUAL_UINT16(0, modemEncodeQueryTelemetry(buf, 7, 0, 0));
}


static void test_C7a_position_carries_a_tracker_fix()
{
    ModemPosition p;
    TEST_ASSERT_TRUE(modemDecodePosition(VEC_POSITION_TRACKER, sizeof(VEC_POSITION_TRACKER), &p));
    TEST_ASSERT_EQUAL_INT32(363596500, p.latitude_i);
    TEST_ASSERT_EQUAL_INT32(72, p.altitude_hae);
    TEST_ASSERT_EQUAL_UINT32(25000u, p.ground_speed_mmps);
    TEST_ASSERT_EQUAL_UINT32(9000000u, p.ground_track);
    TEST_ASSERT_EQUAL_UINT16(80, p.hdop);
    TEST_ASSERT_EQUAL_UINT16(120, p.pdop);
    TEST_ASSERT_EQUAL_UINT16(3000, p.gps_accuracy_mm);
    TEST_ASSERT_EQUAL_UINT8(11, p.sats_in_view);
    TEST_ASSERT_EQUAL_UINT8(3, p.loc_source);
    TEST_ASSERT_EQUAL_UINT8(4, p.alt_source);
}

static void test_C7b_position_round_trips_through_the_encoder()
{
    ModemPosition p;
    TEST_ASSERT_TRUE(modemDecodePosition(VEC_POSITION_TRACKER, sizeof(VEC_POSITION_TRACKER), &p));

    uint8_t out[MODEM_POSITION_SIZE] = {};
    TEST_ASSERT_EQUAL_UINT16(MODEM_POSITION_SIZE, modemEncodePosition(out, sizeof(out), &p));
    TEST_ASSERT_EQUAL_UINT8_ARRAY(VEC_POSITION_TRACKER, out, MODEM_POSITION_SIZE);
    TEST_ASSERT_EQUAL_UINT16(0, modemEncodePosition(out, MODEM_POSITION_SIZE - 1, &p));
}

static void test_C7c_unset_provenance_survives_untouched()
{
    ModemPosition p;
    TEST_ASSERT_TRUE(modemDecodePosition(VEC_POSITION_SOUTH, sizeof(VEC_POSITION_SOUTH), &p));
    TEST_ASSERT_EQUAL_UINT8(0, p.loc_source);
    TEST_ASSERT_EQUAL_UINT8(0, p.alt_source);
}

static void test_C7d_query_position_is_eight_bytes()
{
    uint8_t buf[MODEM_QUERY_POSITION_SIZE] = {};
    TEST_ASSERT_EQUAL_UINT16(8, modemEncodeQueryPosition(buf, sizeof(buf), 0x2EDCA04Cu));
    TEST_ASSERT_EQUAL_HEX8(0x4C, buf[0]);
    TEST_ASSERT_EQUAL_HEX8(0x2E, buf[3]);
    TEST_ASSERT_EQUAL_UINT16(0, modemEncodeQueryPosition(buf, 7, 0));
}

